"""Insula Neuro Score — Neurosurgical Examination & Grades (v0.10).
Each grade below was checked against the sources in its `sources` field before implementation
(verification notes: tools/evidence.py). Descriptors are paraphrased in original wording.
Examination grades describe bedside findings; they are not prognostic scores."""
from library import o, single, st, conf, score

REVIEWED = "2026-10-08"
CAT = "exam"

def opt(id, label, short, options, help=None):
    """Optional descriptive input (side, muscle, site): no points shown in the breakdown."""
    for x in options: x.setdefault("code", "")
    d = single(id, label, short, options, help); d["required"] = False; return d

def build():
    L = []
    def s(**k):
        k.setdefault("category", CAT)
        d = score(**k); d["lastReviewed"] = REVIEWED; return d
    EXAM = lambda label: {"type": "examination-grade", "typeLabel": label, "meter": False}
    SIDE = lambda: opt("side", "Side (optional)", "Side", [o("left", "Left", 0, "L"), o("right", "Right", 0, "R")], help="Recorded for the share text only; it does not change the grade.")

    # ================================================================ MRC muscle power
    mrc_opts = [o(5, "Normal power", 5, "5"), o(4, "Active movement against gravity and resistance", 4, "4"),
                o(3, "Active movement against gravity", 3, "3"), o(2, "Active movement with gravity eliminated", 2, "2"),
                o(1, "Flicker or trace of contraction", 1, "1"), o(0, "No contraction", 0, "0")]
    L.append(s(id="mrc", name="MRC Muscle Power Scale", abbreviation="MRC power", aliases=["mrc", "muscle power", "muscle strength", "power grade", "oxford scale", "manual muscle testing"],
        subcategory="Motor", specialties=["Neurosurgery", "Neurology", "Spine Surgery", "Rehabilitation"],
        version={"label": "Medical Research Council scale, grades 0–5", "detail": "Grades as published in the MRC 'Aids to the investigation of peripheral nerve injuries' (1943; reprinted 1976) and its successor, 'Aids to the Examination of the Peripheral Nervous System'. The booklet notes that grades 4−, 4 and 4+ may be used for slight, moderate and strong resistance; these subdivisions are not offered here."},
        purpose="Records the strength of one muscle or muscle group on a six-point ordinal scale.",
        intendedPopulation="Patients able to cooperate with voluntary muscle testing; any neurological or neuromuscular condition.",
        resultPresentation=EXAM("Muscle power grade"),
        calculatorNotice={"tone": "info", "title": "Examination grade", "message": "Grade one muscle or movement at a time and name it in your notes. The grade describes what was found; it is not a prognosis."},
        inputDefinitions=[single("grade", "Power grade", "MRC", mrc_opts, help="Test against gravity first; if the movement is complete, add resistance. If not, test with gravity eliminated."), SIDE()],
        components=[{"id": "c_grade", "label": "Power grade", "inputs": ["grade"]}, {"id": "c_side", "label": "Side", "inputs": ["side"]}],
        calculationMethod={"type": "select", "input": "grade", "range": {"min": 0, "max": 5}, "display": "{total}/5",
                           "share": "MRC power {total}/5{isnull(side_code) ? '' : ' (' + side_code + ')'}"},
        interpretationRules=[{"when": "total == %d" % i, "state": "g%d" % i} for i in range(6)],
        resultStates=[st("g5", "favorable", "Grade 5: normal power", "Normal power on this test.", "5", "A grade of 5 does not exclude subtle weakness, fatigability or weakness in other muscles.", 5, 5),
                      st("g4", "mild", "Grade 4: against gravity and resistance", "Moves against gravity and some resistance, but less than normal.", "4", "Grade 4 spans a wide range of strength.", 4, 4),
                      st("g3", "moderate", "Grade 3: against gravity", "Moves through the range against gravity, but not against added resistance.", "3", None, 3, 3),
                      st("g2", "high", "Grade 2: gravity eliminated", "Moves only with gravity eliminated.", "2", None, 2, 2),
                      st("g1", "high", "Grade 1: flicker or trace", "Visible or palpable contraction without movement of the joint.", "1", None, 1, 1),
                      st("g0", "high", "Grade 0: no contraction", "No contraction seen or felt.", "0", None, 0, 0)],
        clinicalContext=[{"text": "Describes the strength of one muscle or movement at one examination.", "importance": "major"},
                         {"text": "Most useful as a pattern across muscles (root, nerve, upper motor neuron) and as a trend over time."}],
        clinicalInsights=[{"text": "Record the muscle or movement, the side and the grade together (e.g. left ankle dorsiflexion 3/5)."},
                          {"when": "total == 4", "text": "Grade 4 covers most of the strength range, so small changes within it are not captured."}],
        limitations=[{"importance": "major", "text": "Ordinal scale: steps between grades are not equal, so grades should not be averaged as measurements."},
                     "Grade 4 is broad and insensitive to change.", "Depends on effort, pain and understanding.", "Gravity-eliminated positioning is not always practical."],
        confounders=conf(("Pain or guarding", "Can limit effort and lower the grade."), ("Poor cooperation, sedation or cognitive impairment", "Makes voluntary testing unreliable."),
                         ("Joint contracture or orthopaedic injury", "Limits range independent of strength."), ("Examiner technique", "Position and resistance vary between examiners.")),
        whatItDoesNotTellYou=["The cause or level of the lesion.", "Fatigability or endurance.", "Function in daily activities."],
        commonErrors=["Grading a muscle without stating which muscle or movement was tested.", "Calling partial-range movement against gravity grade 3 (grade 3 requires the full range).",
                      "Averaging MRC grades across muscles as if they were measurements."],
        guideSections={"what": "A six-point scale (0–5) for the strength of a single muscle or movement.",
            "whenToUse": "Motor examination in nerve, root, plexus, spinal cord and brain lesions; serial monitoring.",
            "howToPerform": "Position the limb to test against gravity. If the full range is achieved, apply graded resistance. If not, retest with gravity eliminated, then look and feel for contraction. Record muscle, side and grade.",
            "clinicalContext": "A bedside examination grade; interpret alongside tone, reflexes, sensation and the distribution of weakness."},
        sources=[{"citation": "Medical Research Council. Aids to the investigation of peripheral nerve injuries. War Memorandum No. 7. London: HMSO; 1943 (reprinted 1976)."},
                 {"citation": "Guarantors of Brain. Aids to the Examination of the Peripheral Nervous System. 5th ed. Edinburgh: Saunders Elsevier; 2010."}],
        licensing={"status": "Grade definitions with attribution", "note": "The MRC/Guarantors of Brain booklet and its illustrations are copyrighted and not reproduced; only the grade definitions are paraphrased."}))

    # ================================================================ MRC sum score
    groups = [("sh", "Shoulder abduction"), ("el", "Elbow flexion"), ("wr", "Wrist extension"), ("hi", "Hip flexion"), ("kn", "Knee extension"), ("an", "Ankle dorsiflexion")]
    ss_opts = [o(i, str(i), i, str(i)) for i in (5, 4, 3, 2, 1, 0)]
    NT = {"label": "Not testable", "code": "NT", "reasons": ["Amputation or injury", "Pain prevents testing", "Not cooperating or sedated", "Other"]}
    ss_inputs = []
    for side, sl in (("l", "Left"), ("r", "Right")):
        for gid, gl in groups:
            d = single(gid + "_" + side, "%s, %s" % (gl, sl.lower()), "%s %s" % (sl[0], gl), ss_opts, nt=NT); ss_inputs.append(d)
    L.append(s(id="mrcss", name="MRC Sum Score", abbreviation="MRC-SS", aliases=["mrc sum", "mrc sum score", "icu acquired weakness", "icuaw", "global muscle strength"],
        subcategory="Motor", specialties=["Neurocritical Care", "Critical Care", "Neurology", "Rehabilitation"],
        version={"label": "MRC sum score, 12 muscle groups (Kleyweg et al. 1991)", "detail": "Six movements on each side graded 0–5 with the MRC scale; total 0–60. The <48 threshold for ICU-acquired weakness is from De Jonghe et al. 2002."},
        purpose="Summarises global limb strength from 12 standard movements, for example when assessing ICU-acquired weakness.",
        intendedPopulation="Adults able to follow commands for voluntary strength testing, including critically ill patients once awake and cooperative.",
        resultPresentation={"type": "examination-grade", "typeLabel": "Global muscle strength", "meter": True},
        calculatorNotice={"tone": "info", "title": "Requires an awake, cooperative patient", "message": "If any movement cannot be tested, record it as not testable. No total is reported, because a partial sum is not comparable with the 0–60 scale."},
        components=[{"id": "left", "label": "Left side", "inputs": [d["id"] for d in ss_inputs[:6]]}, {"id": "right", "label": "Right side", "inputs": [d["id"] for d in ss_inputs[6:]]}],
        inputDefinitions=ss_inputs,
        calculationMethod={"type": "sum", "notTestablePolicy": "block", "range": {"min": 0, "max": 60}, "formula": "Left {left} + Right {right}", "display": "{total}/60", "share": "MRC-SS {total}/60 (L {left}, R {right})"},
        notTestable={"label": "No total: movement not testable", "summary": "At least one movement could not be tested, so no MRC sum score is reported.", "display": "No total",
                     "detail": "Report the individual grades. A partial sum is not comparable with the 0–60 scale or the <48 threshold.", "share": "MRC-SS not reported (movement not testable)"},
        interpretationRules=[{"when": "total == 60", "state": "full"}, {"when": "total >= 48", "state": "above"}, {"state": "below"}],
        resultStates=[st("full", "favorable", "No weakness measured", "Full strength in all 12 movements tested.", "60", "Does not exclude distal, proximal-axial or respiratory muscle weakness.", 60, 60),
                      st("above", "mild", "Weakness above the ICU-AW threshold", "Some weakness, with a total at or above 48.", "48–59", "The <48 threshold applies to ICU-acquired weakness; interpret other causes of weakness on their own terms.", 48, 59),
                      st("below", "high", "Below 48: meets the ICU-AW strength criterion", "Total below 48, the strength criterion used to define ICU-acquired weakness (De Jonghe 2002).", "0–47",
                         "ICU-acquired weakness also requires the clinical context and exclusion of other causes; the score alone is not a diagnosis.", 0, 47)],
        clinicalContext=[{"text": "Summarises strength in 12 standard movements into one number.", "importance": "major"},
                         {"text": "A total below 48 is the strength criterion in the definition of ICU-acquired weakness."}],
        clinicalInsights=[{"when": "abs(left - right) >= 6", "importance": "major", "text": "Marked side-to-side difference: a focal (central or peripheral) cause is more likely than generalised ICU-acquired weakness."},
                          {"text": "Repeat after sedation is reduced; early totals in the ICU are often limited by arousal and cooperation."}],
        limitations=[{"importance": "major", "text": "Requires an awake, cooperative patient; often not testable early in critical illness."}, "Insensitive to small changes within MRC grade 4.",
                     "Does not test distal hand, neck, trunk or respiratory muscles.", "Inter-rater agreement is lower in the ICU than in outpatient settings."],
        confounders=conf(("Sedation or delirium", "Reduces effort and cooperation.", ), ("Pain, lines and positioning", "Limit testing of some movements."), ("Pre-existing weakness or joint disease", "Lowers the total independent of the acute illness.")),
        whatItDoesNotTellYou=["The cause of weakness (e.g. myopathy versus neuropathy).", "Respiratory muscle strength.", "Functional mobility."],
        commonErrors=["Summing when one or more movements could not be tested.", "Testing before the patient can follow commands reliably.", "Using the total without checking for asymmetry."],
        guideSections={"what": "The sum of MRC grades for shoulder abduction, elbow flexion, wrist extension, hip flexion, knee extension and ankle dorsiflexion on both sides (0–60).",
            "whenToUse": "Screening and monitoring for ICU-acquired weakness; global strength in Guillain-Barré syndrome and other generalised weakness.",
            "howToPerform": "Confirm the patient is awake and can follow commands. Grade each of the 12 movements with the MRC 0–5 scale. Record any movement that cannot be tested; no total is reported in that case.",
            "clinicalContext": "A summary of limb strength; identifying ICU-acquired weakness also needs clinical context and exclusion of other causes."},
        sources=[{"citation": "Kleyweg RP, van der Meché FG, Schmitz PI. Interobserver agreement in the assessment of muscle strength and functional abilities in Guillain-Barré syndrome. Muscle Nerve. 1991;14(11):1103-1109."},
                 {"citation": "De Jonghe B, Sharshar T, Lefaucheur JP, et al. Paresis acquired in the intensive care unit: a prospective multicenter study. JAMA. 2002;288(22):2859-2867."},
                 {"citation": "Stevens RD, Marshall SA, Cornblath DR, et al. A framework for diagnosing and classifying intensive care unit-acquired weakness. Crit Care Med. 2009;37(10 Suppl):S299-S308."}],
        licensing={"status": "Published method with attribution", "note": "No reproduction restrictions identified."}))

    # ================================================================ Deep tendon reflex (NINDS)
    REFLEX = opt("reflex", "Reflex tested (optional)", "Reflex", [o("biceps", "Biceps", 0), o("brachioradialis", "Brachioradialis", 0), o("triceps", "Triceps", 0),
                 o("knee", "Knee (patellar)", 0), o("ankle", "Ankle (Achilles)", 0), o("other", "Other", 0)], help="Recorded for the share text only.")
    L.append(s(id="dtr", name="Deep Tendon Reflex Grade (NINDS Myotatic Reflex Scale)", abbreviation="Reflex grade", aliases=["dtr", "deep tendon reflex", "tendon reflex", "myotatic reflex", "ninds reflex scale", "reflexes", "hyperreflexia", "areflexia"],
        subcategory="Reflexes", specialties=["Neurology", "Neurosurgery", "Spine Surgery"],
        version={"label": "NINDS Myotatic Reflex Scale, 0–4 (Hallett 1993)", "detail": "0 absent; 1 small or trace, or only with reinforcement; 2 lower half of normal; 3 upper half of normal; 4 enhanced, including clonus if present. Written here as 0–4+ by convention. Other reflex scales (e.g. ones using 5 for sustained clonus) are different versions and are not combined."},
        purpose="Records the amplitude of a muscle stretch reflex on a standard five-point scale.", intendedPopulation="Any patient undergoing neurological examination.",
        resultPresentation=EXAM("Reflex grade"),
        calculatorNotice={"tone": "info", "title": "Compare sides", "message": "Grades 2 and 3 are both within the normal range. Asymmetry, and a change from previous examinations, usually matter more than one value."},
        inputDefinitions=[single("grade", "Reflex amplitude", "Grade", [o(0, "Absent", 0, "0"), o(1, "Small, less than normal", 1, "1+", "Includes a trace response or one brought out only with reinforcement."),
                                                                     o(2, "Lower half of the normal range", 2, "2+"), o(3, "Upper half of the normal range", 3, "3+"),
                                                                     o(4, "Enhanced, more than normal", 4, "4+", "Includes clonus if present; describe the clonus separately.")]), REFLEX, SIDE()],
        components=[{"id": "c_grade", "label": "Amplitude", "inputs": ["grade"]}, {"id": "c_site", "label": "Reflex and side", "inputs": ["reflex", "side"], "showSubtotal": False}],
        calculationMethod={"type": "select", "input": "grade", "range": {"min": 0, "max": 4}, "display": "{grade_code}",
                           "share": "{isnull(reflex_value) ? 'Reflex' : 'Reflex, ' + reflex_value} {grade_code}{isnull(side_code) ? '' : ' (' + side_code + ')'} (NINDS scale)"},
        interpretationRules=[{"when": "total == 0", "state": "absent"}, {"when": "total == 1", "state": "reduced"}, {"when": "total <= 3", "state": "normal"}, {"state": "enhanced"}],
        resultStates=[st("absent", "informational", "Absent", "No reflex obtained, including with reinforcement.", "0", "Interpret with the other reflexes, strength and sensation; isolated absent ankle reflexes can occur in older adults."),
                      st("reduced", "informational", "Reduced", "Reflex smaller than normal, or present only with reinforcement.", "1+"),
                      st("normal", "favorable", "Within the normal range", "Reflex within the normal range (grades 2 and 3).", "2+–3+", "A normal-range reflex can still be abnormal if it differs clearly from the other side."),
                      st("enhanced", "informational", "Enhanced", "Reflex more than normal, which may include clonus.", "4+", "Look for other upper motor neuron signs: tone, spread, clonus and the plantar response.")],
        clinicalContext=[{"text": "Describes the amplitude of one stretch reflex at one examination.", "importance": "major"},
                         {"text": "The pattern across reflexes and sides helps separate upper from lower motor neuron and root lesions."}],
        clinicalInsights=[{"when": "total == 4", "importance": "major", "text": "If clonus is present, record whether it is sustained with the Clonus record in this section."},
                          {"when": "total == 0", "text": "Use reinforcement (e.g. clenching the teeth or Jendrassik manoeuvre) before recording a reflex as absent."}],
        limitations=[{"importance": "major", "text": "Subjective, with moderate inter-rater agreement, particularly between adjacent grades."}, "Normal reflex amplitude varies between people.", "Does not record spread, latency or pendular quality."],
        confounders=conf(("Anxiety or poor relaxation", "Can brisken or suppress reflexes."), ("Age", "Ankle reflexes may be reduced or absent in older adults."), ("Peripheral neuropathy", "Reduces reflexes."), ("Drugs and metabolic state", "Some drugs and metabolic disturbances change reflex amplitude.")),
        whatItDoesNotTellYou=["The site of the lesion on its own.", "Whether a symmetrical brisk reflex is pathological.", "Muscle tone or strength."],
        commonErrors=["Recording a reflex as absent without reinforcement.", "Treating grade 3 as abnormal (it is within the normal range on this scale).", "Mixing this scale with scales that use 5 for sustained clonus."],
        guideSections={"what": "The NINDS Myotatic Reflex Scale grades stretch-reflex amplitude 0–4. Grades 2 and 3 are within the normal range.",
            "whenToUse": "Every neurological examination of the reflexes, and serial assessment of spinal cord, root and nerve lesions.",
            "howToPerform": "Relax and position the limb. Strike the tendon with a consistent technique. If no response, use reinforcement. Grade the amplitude and compare both sides.",
            "clinicalContext": "Interpret with tone, power, sensation, clonus and the plantar response."},
        sources=[{"citation": "Hallett M. NINDS myotatic reflex scale. Neurology. 1993;43(12):2723."},
                 {"citation": "Litvan I, Mangone CA, Werden W, et al. Reliability of the NINDS Myotatic Reflex Scale. Neurology. 1996;47(4):969-972."}],
        licensing={"status": "Published scale with attribution", "note": "No reproduction restrictions identified."}))

    # ================================================================ Clonus (descriptive)
    L.append(s(id="clonus", name="Clonus", abbreviation="Clonus", aliases=["ankle clonus", "patellar clonus", "sustained clonus", "upper motor neuron"],
        subcategory="Reflexes", specialties=["Neurology", "Neurosurgery", "Spine Surgery"],
        version={"label": "Descriptive examination record: absent, unsustained or sustained", "detail": "Standard descriptive terms. Published beat-count thresholds for 'sustained' differ (for example, more than 10 beats in one reference), so no beat threshold is applied; the beat count can be recorded."},
        purpose="Records whether clonus is present at a joint and whether it is sustained.", intendedPopulation="Any patient undergoing neurological examination.",
        resultPresentation=EXAM("Examination finding"),
        calculatorNotice={"tone": "info", "title": "Descriptive record", "message": "This records a finding; it is not a score. Note the joint, the side and the number of beats."},
        inputDefinitions=[single("finding", "Clonus", "Clonus", [o("absent", "No clonus", 0, "Absent"),
                                                              o("unsustained", "Unsustained", 1, "Unsustained", "A limited number of beats that stop although the stretch is maintained."),
                                                              o("sustained", "Sustained", 2, "Sustained", "Rhythmic beats continue for as long as the stretch is maintained.")]),
                          opt("site", "Joint (optional)", "Joint", [o("ankle", "Ankle", 0), o("knee", "Knee (patellar)", 0), o("wrist", "Wrist", 0), o("other", "Other", 0)]),
                          {"id": "beats", "type": "integer", "label": "Number of beats (optional)", "short": "Beats", "min": 1, "max": 100, "required": False}, SIDE()],
        components=[{"id": "c_finding", "label": "Finding", "inputs": ["finding"]}, {"id": "c_detail", "label": "Joint, beats and side", "inputs": ["site", "beats", "side"], "showSubtotal": False}],
        calculationMethod={"type": "select", "input": "finding", "range": {"min": 0, "max": 2}, "display": "{finding_code}",
                           "share": "{finding == 0 ? 'No clonus' : finding_code + ' clonus'}{isnull(site_value) ? '' : ', ' + site_value}{isnull(beats) ? '' : ', ' + beats + ' beats'}{isnull(side_code) ? '' : ' (' + side_code + ')'}"},
        consistencyRules=[{"when": "finding == 0 && !isnull(beats)", "severity": "warning", "inputs": ["beats"], "message": "A beat count is recorded but clonus is marked absent."}],
        interpretationRules=[{"when": "total == 0", "state": "absent"}, {"when": "total == 1", "state": "unsustained"}, {"state": "sustained"}],
        resultStates=[st("absent", "favorable", "No clonus elicited", "No clonus elicited at this examination.", None, "Absence of clonus does not exclude an upper motor neuron lesion."),
                      st("unsustained", "informational", "Unsustained clonus", "A few beats that stop despite maintained stretch.", None, "A few symmetrical unsustained beats can occur without disease; asymmetry and other upper motor neuron signs make it more significant."),
                      st("sustained", "moderate", "Sustained clonus", "Clonus continues while the stretch is maintained.", None, "Sustained clonus is a sign of upper motor neuron dysfunction; correlate with tone, reflexes, the plantar response and the history.")],
        clinicalContext=[{"text": "Clonus is a rhythmic, involuntary contraction triggered by sudden stretch, associated with hyperreflexia.", "importance": "major"},
                         {"text": "Usually tested at the ankle, by brisk and sustained dorsiflexion."}],
        clinicalInsights=[{"when": "finding == 2", "importance": "major", "text": "Record the joint, side and beat count so later examinations can be compared."},
                          {"text": "Compare both sides; asymmetry carries more weight than a symmetrical finding."}],
        limitations=[{"importance": "major", "text": "No single agreed beat count defines 'sustained'; definitions differ between sources."}, "Depends on technique and the force of the stretch.", "Descriptive only; not a severity scale."],
        confounders=conf(("Anxiety, cold or exertion", "Can produce a few unsustained beats."), ("Serotonergic and other drugs", "Can produce clonus."), ("Muscle contracture", "Can prevent eliciting clonus.")),
        whatItDoesNotTellYou=["The site or cause of the lesion.", "The severity of spasticity (see Modified Ashworth and Modified Tardieu)."],
        commonErrors=["Not maintaining the stretch long enough to judge whether clonus is sustained.", "Recording 'sustained' without a beat count or joint."],
        guideSections={"what": "A descriptive record of clonus at a joint: absent, unsustained or sustained.",
            "whenToUse": "Examination for upper motor neuron signs, and monitoring spinal cord or brain lesions.",
            "howToPerform": "Support the limb with the knee slightly flexed. Dorsiflex the foot briskly and hold the stretch. Count the beats and note whether they continue while the stretch is maintained. Repeat on the other side.",
            "clinicalContext": "Interpret with reflex grade, tone, power and the plantar response."},
        sources=[{"citation": "Zimmerman B, Hubbard JB. Clonus. In: StatPearls. Treasure Island (FL): StatPearls Publishing; updated 2023.", "url": "https://www.ncbi.nlm.nih.gov/books/NBK534862/"},
                 {"citation": "Hallett M. NINDS myotatic reflex scale. Neurology. 1993;43(12):2723."}],
        licensing={"status": "Descriptive terms", "note": "No instrument is reproduced."}))

    # ================================================================ Plantar response
    L.append(s(id="plantar", name="Plantar Response", abbreviation="Plantar", aliases=["babinski", "babinski sign", "plantar reflex", "extensor plantar", "upgoing toe"],
        subcategory="Reflexes", specialties=["Neurology", "Neurosurgery", "Spine Surgery"],
        version={"label": "Descriptive examination record: flexor, extensor, equivocal or no response", "detail": "Standard descriptive categories. The extensor response (Babinski sign) is upward movement of the great toe from contraction of extensor hallucis longus."},
        purpose="Records the response of the great toe to stimulation of the lateral sole.", intendedPopulation="Any patient undergoing neurological examination. An extensor response is expected in infants.",
        resultPresentation=EXAM("Examination finding"),
        calculatorNotice={"tone": "info", "title": "Descriptive record", "message": "Record each side separately. An equivocal response is better recorded as equivocal than forced into a category."},
        inputDefinitions=[single("finding", "Great toe response", "Response", [o("flexor", "Flexor", 1, "Flexor", "Great toe flexes (moves down)."),
                                                                            o("extensor", "Extensor", 2, "Extensor", "Great toe extends (moves up) from contraction of extensor hallucis longus; may include fanning of the other toes."),
                                                                            o("equivocal", "Equivocal", 3, "Equivocal", "Response cannot be classified confidently, e.g. withdrawal or mixed movement."),
                                                                            o("none", "No response", 4, "No response", "No toe movement.")]), SIDE()],
        components=[{"id": "c_finding", "label": "Response", "inputs": ["finding"]}, {"id": "c_side", "label": "Side", "inputs": ["side"], "showSubtotal": False}],
        calculationMethod={"type": "select", "input": "finding", "range": {"min": 1, "max": 4}, "display": "{finding_code}",
                           "share": "Plantar response: {finding_code}{isnull(side_code) ? '' : ' (' + side_code + ')'}"},
        interpretationRules=[{"when": "total == 1", "state": "flexor"}, {"when": "total == 2", "state": "extensor"}, {"when": "total == 3", "state": "equivocal"}, {"state": "none"}],
        resultStates=[st("flexor", "favorable", "Flexor response", "Flexor plantar response: the normal finding after infancy.", None, "A flexor response does not exclude an upper motor neuron lesion."),
                      st("extensor", "moderate", "Extensor response (Babinski sign)", "Extensor plantar response.", None, "After infancy this indicates dysfunction of the corticospinal pathway; correlate with tone, reflexes and power."),
                      st("equivocal", "informational", "Equivocal", "Response could not be classified confidently.", None, "Consider repeating, or using alternative stimuli, and interpret with other signs."),
                      st("none", "informational", "No response", "No movement of the great toe.", None, "Can occur with severe weakness, sensory loss or local foot problems.")],
        clinicalContext=[{"text": "An extensor response is one of the most reliable signs of corticospinal tract dysfunction after infancy.", "importance": "major"}],
        clinicalInsights=[{"when": "finding_value == 'extensor'", "importance": "major", "text": "Extensor plantar response: look for associated upper motor neuron signs (hyperreflexia, clonus, spasticity)."},
                          {"text": "Compare both sides; a unilateral extensor response is particularly informative."}],
        limitations=[{"importance": "major", "text": "Inter-observer agreement is only moderate, particularly for equivocal responses."}, "Withdrawal movements can be mistaken for an extensor response.", "Normal in infants."],
        confounders=conf(("Withdrawal response", "Can mimic an extensor response."), ("Foot deformity or great-toe weakness", "Can prevent a visible response."), ("Ticklish or anxious patient", "Leads to withdrawal.")),
        whatItDoesNotTellYou=["The level or cause of the lesion.", "The severity of motor impairment."],
        commonErrors=["Recording withdrawal as an extensor response.", "Forcing an equivocal response into flexor or extensor.", "Using too strong a stimulus."],
        guideSections={"what": "A record of the great-toe response to stimulation of the lateral sole: flexor (normal after infancy), extensor (Babinski sign), equivocal, or no response.",
            "whenToUse": "Every neurological examination where an upper motor neuron lesion is possible.",
            "howToPerform": "With the patient relaxed, stroke the lateral border of the sole from heel towards the little toe, then across the ball of the foot, using a blunt object. Watch the first movement of the great toe. Test both sides.",
            "clinicalContext": "Interpret with reflexes, tone, clonus and power."},
        sources=[{"citation": "van Gijn J. The Babinski reflex. Postgrad Med J. 1995;71(841):645-648."},
                 {"citation": "van Gijn J. The Babinski Sign: A Centenary. Utrecht: Universiteit Utrecht; 1996."}],
        licensing={"status": "Descriptive terms", "note": "No instrument is reproduced."}))

    # ================================================================ Modified Ashworth Scale
