STATE_TEXT[("cognard", "t7")] = (None, "Associated with progressive myelopathy; assess spinal cord function according to the clinical situation.")

def apply_state_text(L):
    for sc in L:
        for stt in sc["resultStates"]:
            k = (sc["id"], stt["id"])
            if k in STATE_TEXT:
                sm, dt = STATE_TEXT[k]
                if sm: stt["summary"] = sm
                if dt: stt["detail"] = dt
    return L

